using System.Net;
using System.Net.Http.Json;
using ClinicaRamirez.Api.Domain.Appointments;
using ClinicaRamirez.Api.Domain.ClinicAdministration;
using ClinicaRamirez.Api.Domain.ClinicalCare;
using ClinicaRamirez.Api.Domain.Identity;
using ClinicaRamirez.Api.Domain.Patients;
using ClinicaRamirez.Api.DTOs.ClinicalCare;
using ClinicaRamirez.Api.Persistence;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Xunit;
namespace ClinicaRamirez.Api.Tests;
public sealed class ClinicalCareTests(IdentityFixture f) : IClassFixture<IdentityFixture>
{
    private sealed record Care(HttpClient Client, Appointment Appointment, Guid User);
    private static ReviewInput Review(Guid? previous=null)=>new(false,previous,false,null,[],[],[]);
    private static StartEncounterRequest Input(ReviewInput? review=null)=>new(null,"Tratamiento",new("Dolor privado","Dos dÃƒÂ­as",null,true,null,true,false,null,5,null),review??Review());
    private static string Url(Care c,string suffix="")=>$"/api/doctor/appointments/{c.Appointment.Id}/clinical{suffix}";
    private static async Task Ok(Task<HttpResponseMessage> task){var r=await task;Assert.True(r.IsSuccessStatusCode,$"{r.StatusCode}: {await r.Content.ReadAsStringAsync()}");}
    private async Task<Care> Setup(bool finance=false)
    {
        var email=await f.CreateUser();using var s=f.Services.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();var user=await db.Users.SingleAsync(x=>x.Email==email);
        var d=new DoctorProfile{UserId=user.Id,ProfessionalLicense=Guid.NewGuid().ToString("N").ToUpperInvariant()};db.Add(d);
        foreach(var role in finance?new[]{"DOCTOR","ADMINISTRATOR"}:new[]{"DOCTOR"})db.UserRoles.Add(new(){UserId=user.Id,RoleId=await db.Roles.Where(x=>x.Code==role).Select(x=>x.Id).SingleAsync()});
        var p=new PatientProfile{User=new User{FirstName="Paciente",LastName="ClÃƒÂ­nico",Ci=Guid.NewGuid().ToString("N").ToUpperInvariant(),BirthDate=new(1990,1,1),Phone="70000000",CanLogin=false},BloodType="UNKNOWN",EmergencyContactName="Prueba",EmergencyContactPhone="70000000"};db.Add(p);db.UserRoles.Add(new(){User=p.User,RoleId=await db.Roles.Where(x=>x.Code=="PATIENT").Select(x=>x.Id).SingleAsync()});
        var center=new Center{ClinicId=Clinic.SingletonId,Code="CL_"+Guid.NewGuid().ToString("N").ToUpperInvariant(),Name="Prueba",Address="Prueba"};db.Add(center);
        var a=new Appointment{DoctorId=d.Id,PatientId=p.Id,CenterId=center.Id,SpecialtyId=await db.Specialties.Select(x=>x.Id).FirstAsync(),AppointmentDate=new(2026,10,14),StartTime=new(9,0),EndTime=new(9,30)};db.Add(a);await db.SaveChangesAsync();var client=f.Client();var login=await f.Login(client,email);client.DefaultRequestHeaders.Authorization=new("Bearer",login.Body.AccessToken);return new(client,a,user.Id);
    }
    private async Task<ClinicalContext> Get(Care c)=>(await c.Client.GetFromJsonAsync<ClinicalContext>(Url(c)))!;
    private async Task<Care> Started(bool finance=false){var c=await Setup(finance);await Ok(c.Client.PostAsJsonAsync(Url(c,"/start"),Input()));return c;}
    private async Task<Care> Second(Care c){using var s=f.Services.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();var a=c.Appointment;var n=new Appointment{DoctorId=a.DoctorId,PatientId=a.PatientId,CenterId=a.CenterId,SpecialtyId=a.SpecialtyId,AppointmentDate=a.AppointmentDate.AddDays(7),StartTime=a.StartTime,EndTime=a.EndTime};db.Add(n);await db.SaveChangesAsync();return c with{Appointment=n};}
    private async Task Plan(Care c){await Ok(c.Client.PostAsJsonAsync(Url(c,"/plan"),new PlanInput("Plan")));await Ok(c.Client.PostAsJsonAsync(Url(c,"/plan/items"),new ProcedureInput("Procedimiento",null,46,null,250m,4)));foreach(var state in new[]{"PROPOSED","ACCEPTED"})await Ok(c.Client.PatchAsJsonAsync(Url(c,"/plan/status"),new ClinicalStatusInput(state)));}
    [Fact] public async Task OwnConsultationAndHeader(){var c=await Started();var x=await Get(c);Assert.Equal("Paciente",x.Patient.FirstName);Assert.NotNull(x.Encounter);Assert.Single(x.Episodes);Assert.Equal("DRAFT",x.Encounter.Soap.Status);}
    [Fact] public async Task AnotherDoctorCannotReadOrWrite(){var c=await Setup();var other=await Setup();foreach(var suffix in new[]{"","/history"})Assert.Equal(HttpStatusCode.NotFound,(await other.Client.GetAsync(Url(c,suffix))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await other.Client.PostAsJsonAsync(Url(c,"/start"),Input())).StatusCode);}
    [Fact] public async Task AuthenticationAndDomainRoleRequired(){var c=await Setup();using var client=f.Client();Assert.Equal(HttpStatusCode.Unauthorized,(await client.GetAsync(Url(c))).StatusCode);var login=await f.Login(client);client.DefaultRequestHeaders.Authorization=new("Bearer",login.Body.AccessToken);Assert.Equal(HttpStatusCode.Forbidden,(await client.GetAsync(Url(c))).StatusCode);}
    [Fact] public async Task ConcurrentStartOnlyOneEncounterSoapReview(){var c=await Setup();foreach(var r in await Task.WhenAll(Enumerable.Range(0,3).Select(_=>c.Client.PostAsJsonAsync(Url(c,"/start"),Input()))))Assert.Equal(HttpStatusCode.NoContent,r.StatusCode);using var s=f.Services.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();var e=Assert.Single(await db.Set<ClinicalEncounter>().Where(x=>x.AppointmentId==c.Appointment.Id).ToArrayAsync());Assert.Single(await db.Set<SoapNote>().Where(x=>x.ClinicalEncounterId==e.Id).ToArrayAsync());Assert.Single(await db.Set<PatientMedicalHistoryReview>().Where(x=>x.PatientProfileId==c.Appointment.PatientId).ToArrayAsync());}
    [Fact] public async Task NewEpisodeRequiresAnamnesisAndRollsBack(){var c=await Setup();Assert.Equal(HttpStatusCode.BadRequest,(await c.Client.PostAsJsonAsync(Url(c,"/start"),Input() with{Anamnesis=null})).StatusCode);Assert.Empty((await Get(c)).Episodes);Assert.Null((await Get(c)).Encounter);}
    [Theory][InlineData("CANCELLED")][InlineData("NO_SHOW")][InlineData("COMPLETED")]
    public async Task InvalidAppointmentStateRejected(string state){var c=await Setup();using var s=f.Services.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();await db.Appointments.Where(x=>x.Id==c.Appointment.Id).ExecuteUpdateAsync(u=>u.SetProperty(x=>x.Status,state));Assert.Equal(HttpStatusCode.Conflict,(await c.Client.PostAsJsonAsync(Url(c,"/start"),Input())).StatusCode);}
    [Fact] public async Task SubsequentSessionReusesEpisodeAndAnamnesis(){var c=await Started();var before=await Get(c);var next=await Second(c);await Ok(next.Client.PostAsJsonAsync(Url(next,"/start"),new StartEncounterRequest(before.Encounter!.TreatmentEpisodeId,null,null,Review(before.LatestReview!.Id) with{NoChanges=true})));var after=await Get(next);Assert.Equal(before.Encounter.TreatmentEpisodeId,after.Encounter!.TreatmentEpisodeId);Assert.NotEqual(before.Encounter.Soap.Id,after.Encounter.Soap.Id);Assert.Equal(before.LatestReview.Id,after.LatestReview!.StateReviewId);using var s=f.Services.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();Assert.Equal(1,await db.Set<TreatmentAnamnesis>().CountAsync(x=>x.TreatmentEpisodeId==before.Encounter.TreatmentEpisodeId));Assert.Equal(2,await db.Set<ClinicalEncounter>().CountAsync(x=>x.TreatmentEpisodeId==before.Encounter.TreatmentEpisodeId));}
    [Fact] public async Task NoAllergyAbsenceInvented(){var c=await Setup();Assert.Null((await Get(c)).LatestReview);await Ok(c.Client.PostAsJsonAsync(Url(c,"/start"),Input()));var r=(await Get(c)).LatestReview!;Assert.False(r.NoKnownAllergies);Assert.Empty(r.Allergies);Assert.Empty(r.Conditions);Assert.Empty(r.Medications);}
    [Fact] public async Task MedicalVersionsPreserveAllCollections(){var c=await Started();var initial=(await Get(c)).LatestReview!;await Ok(c.Client.PostAsJsonAsync(Url(c,"/medical-history"),Review(initial.Id) with{NoKnownAllergies=true}));var confirmed=(await Get(c)).LatestReview!;await Ok(c.Client.PostAsJsonAsync(Url(c,"/medical-history"),Review(confirmed.Id) with{Allergies=[new("Penicilina","Urticaria",null)],Conditions=[new("Asma",null)],Medications=[new("Medicina","10 mg","Diaria",null)]}));var current=await Get(c);Assert.Equal("UNKNOWN",current.Patient.BloodType);Assert.Equal("Penicilina",Assert.Single(current.LatestReview!.Allergies).Name);Assert.Equal("Asma",Assert.Single(current.LatestReview.Conditions).ConditionName);Assert.Equal("Medicina",Assert.Single(current.LatestReview.Medications).MedicationName);var h=(await c.Client.GetFromJsonAsync<ClinicalHistory>(Url(c,"/history")))!;Assert.Equal(3,h.MedicalReviews.Length);Assert.True(h.MedicalReviews.Single(x=>x.Id==confirmed.Id).NoKnownAllergies);Assert.Equal("Penicilina",Assert.Single(h.MedicalReviews[0].Allergies).Name);Assert.Single(h.MedicalReviews[0].Conditions);Assert.Single(h.MedicalReviews[0].Medications);Assert.Equal(h.Events.OrderByDescending(x=>x.At).ThenBy(x=>x.Id),h.Events);}
    [Fact] public async Task StaleReviewNoPartialRows(){var c=await Started();Assert.Equal(HttpStatusCode.Conflict,(await c.Client.PostAsJsonAsync(Url(c,"/medical-history"),Review())).StatusCode);Assert.Single((await c.Client.GetFromJsonAsync<ClinicalHistory>(Url(c,"/history")))!.MedicalReviews);}
    [Fact] public async Task ContradictoryAllergyRejectedAndRollback(){var c=await Setup();Assert.Equal(HttpStatusCode.BadRequest,(await c.Client.PostAsJsonAsync(Url(c,"/start"),Input(Review() with{NoKnownAllergies=true,Allergies=[new("Alergia",null,null)]}))).StatusCode);Assert.Null((await Get(c)).Encounter);Assert.Empty((await Get(c)).Episodes);}
    [Fact] public async Task SoapDraftRevisionSigningAndAddendum(){var c=await Started();var b=new SoapInput("S privado","O privado","A privado","P privado",0);await Ok(c.Client.PutAsJsonAsync(Url(c,"/soap"),b));Assert.Equal(HttpStatusCode.Conflict,(await c.Client.PutAsJsonAsync(Url(c,"/soap"),b)).StatusCode);await Ok(c.Client.PutAsJsonAsync(Url(c,"/soap"),b with{Revision=1,Sign=true}));var n=(await Get(c)).Encounter!.Soap;Assert.Equal("SIGNED",n.Status);Assert.Equal(c.User,n.SignedByUserId);Assert.NotNull(n.SignedAt);Assert.Equal(HttpStatusCode.Conflict,(await c.Client.PutAsJsonAsync(Url(c,"/soap"),b with{Revision=2})).StatusCode);await Ok(c.Client.PostAsJsonAsync(Url(c,"/soap/addenda"),new AddendumInput("CorrecciÃƒÂ³n","Detalle corregido")));Assert.Equal("S privado",(await Get(c)).Encounter!.Soap.Subjective);}
    [Fact] public async Task SigningRequiresCompleteSoap(){var c=await Started();Assert.Equal(HttpStatusCode.BadRequest,(await c.Client.PutAsJsonAsync(Url(c,"/soap"),new SoapInput("S","","","",0,true))).StatusCode);Assert.Equal("DRAFT",(await Get(c)).Encounter!.Soap.Status);}
    [Theory][InlineData(false)][InlineData(true)] public async Task EfHistoricalMutationAndDeletionBlocked(bool delete){var c=await Started();using var s=f.Services.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();var r=await db.Set<PatientMedicalHistoryReview>().SingleAsync(x=>x.PatientProfileId==c.Appointment.PatientId);if(delete)db.Remove(r);else r.Notes="MutaciÃƒÂ³n";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync());}
    [Fact] public async Task SignedSoapEfMutationBlocked(){var c=await Started();await Ok(c.Client.PutAsJsonAsync(Url(c,"/soap"),new SoapInput("S","O","A","P",0,true)));using var s=f.Services.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();var id=(await Get(c)).Encounter!.Soap.Id;var note=await db.Set<SoapNote>().SingleAsync(x=>x.Id==id);note.Subjective="Overwrite";await Assert.ThrowsAsync<InvalidOperationException>(()=>db.SaveChangesAsync(true));}
    [Fact] public async Task PlanTotalSnapshotAndCompletion(){var c=await Started(true);await Plan(c);var p=(await Get(c)).Plan!;Assert.Equal(1000m,p.Total);Assert.Equal(1000m,p.Finance!.AgreedTotal);Assert.Equal(250m,Assert.Single(p.Items).UnitPrice);Assert.Equal(HttpStatusCode.Conflict,(await c.Client.PostAsJsonAsync(Url(c,"/plan/items"),new ProcedureInput("Nuevo",null,null,null,1m))).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await c.Client.PatchAsJsonAsync(Url(c,"/plan/status"),new ClinicalStatusInput("COMPLETED"))).StatusCode);foreach(var status in new[]{"IN_PROGRESS","COMPLETED"})await Ok(c.Client.PatchAsJsonAsync(Url(c,"/plan/status"),new ClinicalStatusInput(status)));Assert.Equal("COMPLETED",Assert.Single((await Get(c)).Episodes).Status);}
    [Fact] public async Task ConcurrentPlanUnique(){var c=await Started();var results=await Task.WhenAll(Enumerable.Range(0,2).Select(_=>c.Client.PostAsJsonAsync(Url(c,"/plan"),new PlanInput("Plan"))));Assert.Single(results,x=>x.StatusCode==HttpStatusCode.NoContent);Assert.Single(results,x=>x.StatusCode==HttpStatusCode.Conflict);}
    [Fact] public async Task PaymentsBalanceFullAndOverpayment(){var c=await Started(true);await Plan(c);await Ok(c.Client.PostAsJsonAsync(Url(c,"/payments"),new PaymentInput(Guid.NewGuid(),300m,"Efectivo",null,null)));var p=(await Get(c)).Plan!.Finance!;Assert.Equal(300m,p.PaidTotal);Assert.Equal(700m,p.PendingBalance);Assert.Equal("PENDING",p.PaymentStatus);Assert.Equal(HttpStatusCode.Conflict,(await c.Client.PostAsJsonAsync(Url(c,"/payments"),new PaymentInput(Guid.NewGuid(),701m,null,null,null))).StatusCode);await Ok(c.Client.PostAsJsonAsync(Url(c,"/payments"),new PaymentInput(Guid.NewGuid(),700m,null,null,null)));p=(await Get(c)).Plan!.Finance!;Assert.Equal(0m,p.PendingBalance);Assert.Equal("PAID",p.PaymentStatus);Assert.Equal(2,p.Payments.Length);}
    [Fact] public async Task ConcurrentPaymentIdempotency(){var c=await Started(true);await Plan(c);var p=new PaymentInput(Guid.NewGuid(),300m,null,null,null);foreach(var r in await Task.WhenAll(Enumerable.Range(0,3).Select(_=>c.Client.PostAsJsonAsync(Url(c,"/payments"),p))))Assert.Equal(HttpStatusCode.NoContent,r.StatusCode);Assert.Single((await Get(c)).Plan!.Finance!.Payments);Assert.Equal(HttpStatusCode.Conflict,(await c.Client.PostAsJsonAsync(Url(c,"/payments"),p with{Amount=301m})).StatusCode);}
    [Fact] public async Task ConcurrentPaymentsNoOverdraft(){var c=await Started(true);await Plan(c);var results=await Task.WhenAll(Enumerable.Range(0,2).Select(_=>c.Client.PostAsJsonAsync(Url(c,"/payments"),new PaymentInput(Guid.NewGuid(),700m,null,null,null))));Assert.Single(results,x=>x.StatusCode==HttpStatusCode.NoContent);Assert.Single(results,x=>x.StatusCode==HttpStatusCode.Conflict);Assert.Equal(300m,(await Get(c)).Plan!.Finance!.PendingBalance);}
    [Fact] public async Task FinancialPermissionsRequired(){var c=await Started();await Plan(c);Assert.Null((await Get(c)).Plan!.Finance);Assert.Equal(HttpStatusCode.Forbidden,(await c.Client.PostAsJsonAsync(Url(c,"/payments"),new PaymentInput(Guid.NewGuid(),1m,null,null,null))).StatusCode);}
    [Fact] public async Task AuditNoClinicalText(){var c=await Started(true);await Plan(c);await Ok(c.Client.PutAsJsonAsync(Url(c,"/soap"),new SoapInput("PRIVATE S","PRIVATE O","PRIVATE A","PRIVATE P",0,true)));await Ok(c.Client.PostAsJsonAsync(Url(c,"/payments"),new PaymentInput(Guid.NewGuid(),1m,null,null,"PRIVATE PAYMENT")));using var s=f.Services.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();var logs=await db.AuditLogs.Where(x=>x.UserId==c.User).ToArrayAsync();foreach(var action in new[]{"clinical_encounter_started","medical_history_updated","treatment_episode_created","soap_note_signed","treatment_plan_created","treatment_plan_updated","payment_recorded"})Assert.Contains(logs,x=>x.Action==action);Assert.DoesNotContain("PRIVATE",string.Join(" ",logs.Select(x=>x.MetadataJson)));}
    [Fact] public void ClinicalModelNormalizedAndRestrict(){using var s=f.Services.CreateScope();var db=s.ServiceProvider.GetRequiredService<AppDbContext>();var entities=db.Model.GetEntityTypes().Where(x=>typeof(IClinicalRecord).IsAssignableFrom(x.ClrType)).ToArray();Assert.Equal(13,entities.Length);Assert.All(entities.SelectMany(x=>x.GetForeignKeys()),fk=>Assert.Equal(DeleteBehavior.Restrict,fk.DeleteBehavior));Assert.DoesNotContain(entities.SelectMany(x=>x.GetProperties()),p=>p.GetColumnType() is "json" or "jsonb");}
}
